function sliderServices() {
    var swiper = new Swiper('.services .mySwiper', {
        slidesPerView: 1,
        spaceBetween: 20,
        speed: 1200,
        slideToClickedSlide: true,
        navigation: {
            nextEl: ".services .swiper-button-next",
            prevEl: ".services .swiper-button-prev",
        },
        breakpoints: {
            320: {
                spaceBetween: 10,
            },
            993: {
                spaceBetween: 20,
            },
        }
    });
}

function planGallery() {
    let SlidersArray = []

    let sliders = document.querySelectorAll(".plan__images")
    sliders.forEach((slider, index) => {
        slider.setAttribute("data-slider-id", index)
        let gallery = {
            mySwiper: {},
            mySwiper2: {}
        }

        gallery.mySwiper = new Swiper(`.plan__images[data-slider-id="${index}"] .mySwiper`, {
            slidesPerView: 4,
            spaceBetween: 16,
            freeMode: true,
        });

        gallery.mySwiper2 = new Swiper(`.plan__images[data-slider-id="${index}"] .mySwiper2`, {
            spaceBetween: 16,
            slidesPerView: 1,
            navigation: {
                nextEl: `.plan__images[data-slider-id="${index}"] .swiper-button-next`,
                prevEl: `.plan__images[data-slider-id="${index}"] .swiper-button-prev`,
            },
            thumbs: {
                swiper: gallery.mySwiper,
            },
        });

        SlidersArray[index] = gallery
    })
}

function sliderPlanMob() {
    var swiper = new Swiper('.plan-mob .mySwiper', {
        slidesPerView: 1,
        spaceBetween: 20,
        effect: "fade",
        direction: "vertical",
    });

    let atLastSlide = false;

    swiper.on('slideChange', function () {
        atLastSlide = swiper.isEnd;
    });

    swiper.on('touchEnd', function () {
        if (atLastSlide && swiper.touches.diff < 0) {
            const planMobElem = document.querySelector('.plan-mob');
            if (planMobElem) {
                planMobElem.remove();
            }
        }
    });
}

