function sliderStages() {
  var swiper = new Swiper(".stages__wrap .mySwiper", {
    slidesPerView: 4,
    spaceBetween: 16,
    freeMode: true,
  });

  var swiper2 = new Swiper(".stages__wrap .mySwiper2", {
    slidesPerView: 1,
    spaceBetween: 0,
    speed: 1200,
    direction: "vertical",
    // mousewheel: true,
    mousewheel: {
      releaseOnEdges: true,
    },
    touchReleaseOnEdges: true, 
    autoHeight: true,
    thumbs: {
      swiper: swiper,
    },
    pagination: {
      el: ".stages__pagination",
      type: "progressbar",
    },
    breakpoints: {
      320: {
        slidesPerView: 1,
        spaceBetween: 50,
        mousewheel: false,
        touchReleaseOnEdges: true, 
      },
      993: {
        slidesPerView: 1,
        spaceBetween: 0,
      },
    },
  });

  function updateActiveYear() {
    const activeIndex = swiper2.activeIndex;
    const activeMonthSlide = swiper.slides[activeIndex];
    const activeMonth = activeMonthSlide ? activeMonthSlide.getAttribute('data-month') : null;

    if (activeMonth) {
      document.querySelectorAll('.year').forEach(year => {
        year.classList.remove('year--active');
      });

      const activeYear = document.querySelector(`.year[data-year="${activeMonth}"]`);
      if (activeYear) {
        activeYear.classList.add('year--active');
      }
    }
  }

  updateActiveYear();

  swiper2.on('slideChange', updateActiveYear);

  document.querySelectorAll('.year').forEach(year => {
    year.addEventListener('click', function() {
      const selectedYear = this.getAttribute('data-year');

      let targetIndex = -1;
      swiper.slides.forEach((slide, index) => {
        if (slide.getAttribute('data-month') === selectedYear && targetIndex === -1) {
          targetIndex = index;
        }
      });

      if (targetIndex !== -1) {
        swiper2.slideTo(targetIndex);
      }
    });
  });
}


$(document).ready(function () {
    sliderServices();
    planGallery();
    sliderPlanMob();
    sliderAboutAdvantages();
    sliderHouseMain();
    sliderArticleNews();
    sliderStages();

    // Menu
    $('.burger').click(function () {
        $(this).toggleClass('burger--active')
        $('.menu').toggleClass('menu--active')
        $('body').toggleClass('fixed-body')
    })

    // Btn-animation
    $(".btn-animation").mouseenter(function(e) {
        var $this = $(this);
        var $animation = $this.find(".circle");
        var offset = $this.offset();
        var x = e.pageX - offset.left;
        var y = e.pageY - offset.top;
        $animation.css({
            top: y + 'px',
            left: x + 'px'
        });
    });

    $(".btn-animation").mousemove(function(e) {
        var $this = $(this);
        var $animation = $this.find(".circle");
        var offset = $this.offset();
        var x = e.pageX - offset.left;
        var y = e.pageY - offset.top;
        $animation.css({
            top: y + 'px',
            left: x + 'px'
        });
    });

    // Form
    let isClicked = false;
    $('.form').on('submit', function(e) {
        e.preventDefault();

        isClicked = true;
        let allFilled = true;

        $(this).find('.form-group input').each(function() {
            const $input = $(this);
            const $formGroup = $input.closest('.form-group');

            if ($input.val().trim() === '') {
                $formGroup.addClass('form-group--active');
                allFilled = false;
            } else {
                $formGroup.removeClass('form-group--active');
            }
        });
    });
    $('.form-group input').on('input', function() {
        if (isClicked) {
            const $input = $(this);
            const $formGroup = $input.closest('.form-group');

            if ($input.val().trim() === '') {
                $formGroup.addClass('form-group--active');
            } else {
                $formGroup.removeClass('form-group--active');
            }
        }
    });

    // Up
    var t = $(".up");

    $(window).scroll(function() {
        if ($(window).scrollTop() > 300) {
            t.addClass("up--active");
        } else {
            t.removeClass("up--active");
        }
    });

    t.on("click", function(e) {
        e.preventDefault();
        $("html, body").animate({
            scrollTop: 0
        }, 300);
    });

    // Modal
    $("[data-modal]").click(function () {
        let modalId = $(this).attr("data-modal")

        openModal(modalId)
    })

    function openModal(modalId){
        $(`#${modalId}`).addClass("modal--active")
        $("body").addClass("fixed-body2")
    }

    $(".modal").click(function () {
        closeModal()
    })

    $("._close-modal").click(function () {
        closeModal()
    })

    $(".modal__dialog").click(function (e) {
        e.stopPropagation()
    })

    function closeModal() {
        $('.modal--active video').each(function () {
            this.pause();
            this.currentTime = 0;
        });
        
        $('.modal').removeClass("modal--active")
        $("body").removeClass("fixed-body2")
    }

    // Cookies
    $('.cookies__btn').click(function () {
        $(this).parents('.cookies').remove()
    })

    $('.cookies__close').click(function () {
        $(this).parents('.cookies').remove()
    })

    // hover slider
    $(".hover__pag-item").mouseover(function() {
        let path = $(this).attr("data-tab-path")
        $(this).parents(".hover__slide").find(".hover__pag-item").removeClass("hover__pag-item--active")
        $(this).addClass("hover__pag-item--active")
        $(this).parents(".hover__slide").find(".hover__img").removeClass("hover__img--active")
        $(this).parents(`.hover__slide`).find(`.hover__img[data-tab-path="${path}"]`).addClass("hover__img--active")
        $(this).parents(".hover__slide").find(".pagination-bullet").removeClass("pagination-bullet--active")
        $(this).parents(`.hover__slide`).find(`.pagination-bullet[data-tab-path="${path}"]`).addClass("pagination-bullet--active")
    })

    // Tabs
    $(".tab").click((function() {
        let e = $(this).attr("data-tab-path");
        $(this).siblings(".tab").removeClass("tab--active"),
        $(this).addClass("tab--active"),
        $(this).parents(".tabs-inner").find(".tab__content").removeClass("tab__content--active"),
        $(this).parents(".tabs-inner").find(`.tab__content[data-content-path="${e}"]`).addClass("tab__content--active")
        }
    ))    


});
    // Animation

    //Services
    document.addEventListener('DOMContentLoaded', () => {
        const targets = gsap.utils.toArray('.services .section-top');

        targets.forEach(el => {
            gsap.set(el, {opacity: 0, y: 80, transformOrigin: 'center center', willChange: 'transform, opacity' });
        });

        const io = new IntersectionObserver((entries, obs) => {
            entries.forEach(entry => {
                const el = entry.target;
                if (entry.isIntersecting) {
                    if (!el._gsapTriggered) {
                        el._gsapTriggered = true;
                        gsap.to(el, {
                            opacity: 1,
                            y: 0,
                            ease: 'power3.out',
                            duration: 1.5,
                            scrollTrigger: {
                                trigger: el,
                                start: 'top 80%',
                                end: 'top 40%',
                            }
                        });

                        obs.unobserve(el);
                    }
                }
            });
            }, {
                    threshold: 0.05
            });

            targets.forEach(el => io.observe(el));
    });
    const serviceTimeline = gsap.timeline({ paused: true });
	const observerServices = new IntersectionObserver((entries, observer) => {
		entries.forEach(entry => {
			if (entry.isIntersecting) {
				serviceTimeline.clear();

				document.querySelectorAll('.services__slider .swiper-slide').forEach((item, index) => {
					serviceTimeline.to(item, {
						opacity: 1,
						y: 0,
						duration: 0.6,
						ease: 'power2.out'
					});
				});

				serviceTimeline.play();
				observer.disconnect();
			}
		});
	}, { threshold: 0.5 });
	const servicesSection = document.querySelector('.services__slider');
	if (servicesSection) {
		observerServices.observe(servicesSection);
	}

    // Area2
    document.addEventListener('DOMContentLoaded', () => {
        const targets = gsap.utils.toArray('.area2__inner');

        targets.forEach(el => {
            gsap.set(el, {opacity: 0, y: 80, transformOrigin: 'center center', willChange: 'transform, opacity' });
        });

        const io = new IntersectionObserver((entries, obs) => {
            entries.forEach(entry => {
                const el = entry.target;
                if (entry.isIntersecting) {
                    if (!el._gsapTriggered) {
                        el._gsapTriggered = true;
                        gsap.to(el, {
                            opacity: 1,
                            y: 0,
                            ease: 'power3.out',
                            duration: 1.5,
                            scrollTrigger: {
                                trigger: el,
                                start: 'top 80%',
                                end: 'top 40%',
                            }
                        });

                        obs.unobserve(el);
                    }
                }
            });
            }, {
                    threshold: 0.05
            });

            targets.forEach(el => io.observe(el));
    });

    //House-main
	document.addEventListener('DOMContentLoaded', () => {

		const targets = gsap.utils.toArray(
			'.house-main__group'
		);

		gsap.set(targets, { opacity: 0, y: 60, willChange: 'transform, opacity' });

		gsap.to(targets, {
			opacity: 1,
			y: 0,
			duration: 1.5,
			ease: 'power3.out',
			stagger: 0.06,
			overwrite: true
		});
	});

	//House-plan
	document.addEventListener('DOMContentLoaded', () => {
		const targets = gsap.utils.toArray('.house-plan .section-top');

		targets.forEach(el => {
			gsap.set(el, { opacity: 0, y: 80, transformOrigin: 'center center', willChange: 'transform, opacity' });
		});

		const io = new IntersectionObserver((entries, obs) => {
			entries.forEach(entry => {
				const el = entry.target;
				if (entry.isIntersecting) {
					if (!el._gsapTriggered) {
						el._gsapTriggered = true;
						gsap.to(el, {
							opacity: 1,
							y: 0,
							ease: 'power3.out',
							duration: 1.5,
							scrollTrigger: {
								trigger: el,
								start: 'top 80%',
								end: 'top 40%',
							}
						});

						obs.unobserve(el);
					}
				}
			});
		}, {
			threshold: 0.05
		});

		targets.forEach(el => io.observe(el));
	});

	//House-presentation
	document.addEventListener('DOMContentLoaded', () => {
		const targets = gsap.utils.toArray('.house-presentation__group');

		targets.forEach(el => {
			gsap.set(el, { opacity: 0, y: 80, transformOrigin: 'center center', willChange: 'transform, opacity' });
		});

		const io = new IntersectionObserver((entries, obs) => {
			entries.forEach(entry => {
				const el = entry.target;
				if (entry.isIntersecting) {
					if (!el._gsapTriggered) {
						el._gsapTriggered = true;
						gsap.to(el, {
							opacity: 1,
							y: 0,
							ease: 'power3.out',
							duration: 1.5,
							scrollTrigger: {
								trigger: el,
								start: 'top 80%',
								end: 'top 40%',
							}
						});

						obs.unobserve(el);
					}
				}
			});
		}, {
			threshold: 0.05
		});

		targets.forEach(el => io.observe(el));
	});

	









